import{_ as l,l as r,o as e,c as n,v as t,p as s,x as i,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"对准策略与 SPM","description":"","frontmatter":{"title":"对准策略与 SPM","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/alignment-spm.md","filePath":"litho/alignment-spm.md","lastUpdated":1789023840000}'),S={name:"litho/alignment-spm.md"};function m(c,a,E,A,P,_){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="对准策略与-spm" tabindex="-1">对准策略与 SPM <a class="header-anchor" href="#对准策略与-spm" aria-label="Permalink to &quot;对准策略与 SPM&quot;">​</a></h1><div class="epigraph"><p>曝光前必须知道晶圆在台子上的哪一点；对准传感器读标记，工件台位置监测把这张读数钉到编码器网格上，策略决定用哪些色、哪些点去拟合变形。</p><footer>—— 据 ASML 对准传感器与对准策略的公开论述，以及与对准互补的工件台位置监测（SPM）</footer></div><p><a href="/litho/chiplet-packaging">上一课</a>把算力涨到封装侧，并不减小裸片内部层与层之间的纳米对准。缺口是扫描机里的对准：标记怎么选、多色如何压工艺不对称，以及 Stage Position Monitoring（SPM）如何把传感器读数和台位差一起喂给网格。掩模热膨胀从下一课才进套刻账单；本课先把「曝光前网格」钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/litho-overlay">套刻 Overlay</a> 已经区分对准与曝光后 overlay。<a href="/litho/overlay-marks">套刻标记</a>写过 IBO/DBO 验收。缺口是机内策略：晶圆进机只有几十微米级预对准，要靠划片道光栅走到亚纳米网格。ASML 公开把 SMASH 再到 ORION 写成多波长、偏振更丰富的对准传感器，用最优颜色加权（OCW）把标记倾斜与工艺变形从位移里分开。</p><p>仅有传感器不够。台子被命令走到某处，编码器读到的路径仍有残差。公开专利叙述里，SPM 与对准传感器互补：监测晶圆台（或掩模台）相对计量架的位置/运动，把「传感器积分期间台子晃了多少」补进算法。没有 SPM，对准策略只是一张好看的色权重。</p><h3 id="标记策略不是越多越好" tabindex="-1">标记策略不是越多越好 <a class="header-anchor" href="#标记策略不是越多越好" aria-label="Permalink to &quot;标记策略不是越多越好&quot;">​</a></h3><p>点太少，翘曲和高阶场拟合不足；太多，测量时间吃片周期——双台把测量藏进曝光，仍不是无限。策略包括：用哪一层留下的标记、哪几个衍射级、哪几色、是否场内加密。工艺改 CMP 或膜厚，策略要重选，不是机台规格书上的单机 overlay 自动继承。</p><p><span class="marginnote">ORION 相对 SMASH 的公开卖点是更多色信号、对标记变形更不敏感。它不把产品套刻变成零。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对准策略是一张配方：标记类型、采样图、模型阶数（线性到高阶晶圆对准 HOWA）、色与偏振权重。OCW 把多色读数组合成对不对称更钝的位移。混合计量可以把调平高度图的一部分信息喂进网格，公开论文称为 holistic 控制的一支。本课不展开 APC 软件商标。</p><p>SPM：在计量架上用编码器等读台位，与对准积分同步或加权，抑制传感器与台环路之间的串扰。对准闪光时台子并非理想静止，SPM 提供那段时间的位置修正。把它理解成「又一个对准波长」是错的——它不看晶圆标记，只看台。</p>',12)),(e(),s(d,null,{default:i(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MK%5B%22%E6%99%B6%E5%9C%86%E5%AF%B9%E5%87%86%E6%A0%87%E8%AE%B0%22%5D%20--%3E%20SNS%5B%22SMASH%20%2F%20ORION%20%E5%A4%9A%E8%89%B2%22%5D%0A%20%20SPM%5B%22SPM%20%E5%8F%B0%E4%BD%8D%E7%9B%91%E6%B5%8B%22%5D%20--%3E%20ALG%5B%22%E5%AF%B9%E5%87%86%E7%AE%97%E6%B3%95%22%5D%0A%20%20SNS%20--%3E%20ALG%0A%20%20ALG%20--%3E%20GRID%5B%22%E6%9B%9D%E5%85%89%E7%BD%91%E6%A0%BC%22%5D%0A%20%20STR%5B%22%E7%AD%96%E7%95%A5%3A%20%E9%87%87%E6%A0%B7%20%2F%20%E8%89%B2%E6%9D%83%E9%87%8D%20%2F%20%E9%98%B6%E6%95%B0%22%5D%20--%3E%20ALG%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="与封装对准不要混名" tabindex="-1">与封装对准不要混名 <a class="header-anchor" href="#与封装对准不要混名" aria-label="Permalink to &quot;与封装对准不要混名&quot;">​</a></h3><p>Chiplet 与混合键合有自己的键合对准，精度语言是微米到亚微米凸点，不是扫描机里的纳米网格。本课对象是前道/后道光刻层。把 CoWoS 的贴片精度写成 ORION 的指标，类别错误。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>标记是光栅，对准光的衍射级相位编码位移。膜层使有效光学中心偏离几何中心，且随波长变——多色差就是不对称的诊断。策略用这组差去估计「真位移」，而不是平均掉。SPM 把台环的动态误差从标记相位里拆走，否则会把振动写成晶圆变形。</p><p>高阶模型用更多点拟合扫描方向的放大、偏扭和工艺指纹。点的布局决定能看见哪些阶；看见不等于应该补偿——过度拟合会把计量噪声写进曝光。<a href="/litho/twinscan-dual-stage">双工件台</a>把加密采样放在测量位，使策略可以密而不直接吃曝光时间；SPM 仍要在曝光位跟上扫描同步，两段时间轴不要混。</p><p><span class="marginnote">单机套刻、匹配套刻、产品套刻仍是三个数。对准策略改的是产品网格的输入质量，不改定义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把未公开的对准残差纳米表填进来。不要重写编码器网格原理——TWINSCAN 课已经说过平面电机与短光束。本课也不把 DBO 套刻计量机当成 SPM。下一课的掩模加热是曝光期间的热源，对准网格若在曝光前测完，仍会被曝光中的掩模膨胀改掉，必须另开校正。</p><p><span class="marginnote">出处：ASML 对准公开故事与 ORION / OCW 产品论述；对准方法专利中对 SPM（stage position monitoring）与对准传感器互补的描述。不引用未公开的内部对准食谱。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对准策略选择标记、色、采样与模型阶数，把工艺变形从位移里分开。</li><li>SPM 监测台位，与对准传感器互补，不是又一路看标记的光。</li><li>封装对准与扫描机纳米网格不是同一指标。</li><li>曝光中的掩模热下一课才会改已经测好的网格。</li><li>出处：ASML 对准公开材料；SPM 公开专利表述。</li></ul>',11))])}const u=l(S,[["render",m]]);export{M as __pageData,u as default};
